contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public payable {
        // avoid division by zero in collateralFor used inside requestLoan
        require(loanToCollateral != 0, "bad_ltv");

        bool reverted;
        uint256 reqID;

        uint256 id = c.requestLoan(amount, interest, loanToCollateral, duration); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            reqID = type(uint256).max;
        } else {
            reverted = false;
            reqID = id;
        }

        // General rule: if the call did not revert then the created request id must be active
        assert(reverted || c.isActive(reqID));
    }

    receive() external payable { }
}

